#include <vector>
#include <string>
#include <numeric>
#include <algorithm>

class Solution {
public:
    std::string largestMultipleOfThree(std::vector<int>& digits) {
        int total = std::accumulate(digits.begin(), digits.end(), 0);
        std::sort(digits.rbegin(), digits.rend());
        std::vector<int> m1, m2;
        for (int i = (int)digits.size() - 1; i >= 0; --i) {
            if (digits[i] % 3 == 1) m1.push_back(digits[i]);
            else if (digits[i] % 3 == 2) m2.push_back(digits[i]);
        }
        std::vector<int> toRemove;
        if (total % 3 == 1) {
            if (!m1.empty()) toRemove.push_back(m1[0]);
            else if (m2.size() >= 2) { toRemove.push_back(m2[0]); toRemove.push_back(m2[1]); }
            else return "";
        } else if (total % 3 == 2) {
            if (!m2.empty()) toRemove.push_back(m2[0]);
            else if (m1.size() >= 2) { toRemove.push_back(m1[0]); toRemove.push_back(m1[1]); }
            else return "";
        }
        for (int rem : toRemove) {
            for (auto it = digits.end() - 1; it >= digits.begin(); --it) {
                if (*it == rem) { digits.erase(it); break; }
            }
        }
        if (digits.empty()) return "";
        if (digits[0] == 0) return "0";
        std::string res = "";
        for (int d : digits) res += std::to_string(d);
        return res;
    }
};

import java.util.*;

class Solution {
    public String largestMultipleOfThree(int[] digits) {
        int total = 0;
        for (int d : digits) total += d;
        Arrays.sort(digits);
        List<Integer> list = new ArrayList<>();
        for (int d : digits) list.add(d);
        Collections.reverse(list);
        List<Integer> m1 = new ArrayList<>(), m2 = new ArrayList<>();
        for (int i = list.size() - 1; i >= 0; i--) {
            if (list.get(i) % 3 == 1) m1.add(list.get(i));
            else if (list.get(i) % 3 == 2) m2.add(list.get(i));
        }
        List<Integer> toRemove = new ArrayList<>();
        if (total % 3 == 1) {
            if (!m1.isEmpty()) toRemove.add(m1.get(0));
            else if (m2.size() >= 2) { toRemove.add(m2.get(0)); toRemove.add(m2.get(1)); }
            else return "";
        } else if (total % 3 == 2) {
            if (!m2.isEmpty()) toRemove.add(m2.get(0));
            else if (m1.size() >= 2) { toRemove.add(m1.get(0)); toRemove.add(m1.get(1)); }
            else return "";
        }
        for (int rem : toRemove) {
            for (int i = list.size() - 1; i >= 0; i--) {
                if (list.get(i) == rem) { list.remove(i); break; }
            }
        }
        if (list.isEmpty()) return "";
        if (list.get(0) == 0) return "0";
        StringBuilder sb = new StringBuilder();
        for (int d : list) sb.append(d);
        return sb.toString();
    }
}

var largestMultipleOfThree = function(digits) {
    let total = digits.reduce((acc, d) => acc + d, 0);
    digits.sort((a, b) => b - a);
    const m1 = digits.filter(d => d % 3 === 1).sort((a, b) => a - b);
    const m2 = digits.filter(d => d % 3 === 2).sort((a, b) => a - b);
    let toRemove = [];
    if (total % 3 === 1) {
        if (m1.length > 0) toRemove = [m1[0]];
        else if (m2.length >= 2) toRemove = [m2[0], m2[1]];
        else return "";
    } else if (total % 3 === 2) {
        if (m2.length > 0) toRemove = [m2[0]];
        else if (m1.length >= 2) toRemove = [m1[0], m1[1]];
        else return "";
    }
    for (const rem of toRemove) {
        for (let i = digits.length - 1; i >= 0; i--) {
            if (digits[i] === rem) {
                digits.splice(i, 1);
                break;
            }
        }
    }
    if (digits.length === 0) return "";
    if (digits[0] === 0) return "0";
    return digits.join("");
};
